async function assertCanControlAgentLifecycle(req, targetAgent) {
    if (req.actor.type === "board") return;
    assertCompanyAccess(req, targetAgent.companyId);
    if (req.actor.type !== "agent" || !req.actor.agentId)
        throw forbidden("Board or active company CEO required");
    const caller = await svc.getById(req.actor.agentId);
    if (!caller || caller.companyId !== targetAgent.companyId || caller.role !== "ceo" ||
        ["paused", "terminated", "pending_approval"].includes(caller.status))
        throw forbidden("Active company CEO required");
    // Do not turn lifecycle control into an implicit hire approval decision.
    if (targetAgent.status === "pending_approval")
        throw forbidden("Pending hire decisions require Board access");
    const decision = await access.decide({
        actor: req.actor,
        action: "agent_config:update",
        resource: { type: "agent", companyId: targetAgent.companyId, agentId: targetAgent.id },
        scope: { requiresChangeGrant: true, targetAgentId: targetAgent.id },
    });
    if (!decision.allowed)
        throw forbidden(decision.explanation, authorizationDeniedDetails(decision));
}
