router.post("/heartbeat-runs/:runId/cancel", async (req, res) => {
    if (req.actor.type !== "agent") assertBoard(req);
    const runId = readHeartbeatRunId(req);
    const existing = await getAccessibleResource(req, res, heartbeat.getRun(runId), "Heartbeat run not found");
    if (!existing)
        return;
    if (req.actor.type === "agent") {
        const target = await getAccessibleResource(req, res, svc.getById(existing.agentId), "Agent not found");
        if (!target) return;
        await assertCanControlAgentLifecycle(req, target);
    }
    const actor = getActorInfo(req);
    // Server-generated cancellation attribution, never accepted from request data.
    const isCeo = req.actor.type === "agent";
    const run = await heartbeat.cancelRun(runId, isCeo ? "Cancelled by company CEO" : "Cancelled by a board operator", isCeo ? {
        errorCode: "ceo_cancelled",
        suppressImmediateRecovery: true,
        resultJson: {
            cancelledByActorType: "agent",
            cancelledByAgentId: actor.agentId,
            cancelledByRunId: actor.runId,
            cancelledByKeyId: actor.agentApiKeyId,
            ceoLifecycleCancellation: { runId: existing.id, companyId: existing.companyId },
        },
    } : {
        resultJson: {
            cancelledByActorType: "user",
            cancelledByUserId: req.actor.userId ?? null,
        },
    });
    if (run) {
        await logActivity(db, {
            companyId: run.companyId,
            ...actor,
            action: "heartbeat.cancelled",
            entityType: "heartbeat_run",
            entityId: run.id,
            details: { agentId: run.agentId },
        });
    }
    res.json(run);
});

